"""Reproduce the four bounded examples generated by the updated-skill evaluation."""

def premise():
    import unicodedata
    names = ["Café"]
    composed, decomposed = "Café", "Cafe\u0301"
    def search(query, corrected=False):
        def key(text):
            if corrected:
                return unicodedata.normalize("NFC", unicodedata.normalize("NFC", text).casefold())
            return text.casefold()
        return [name for name in names if key(name) == key(query)]
    # This fresh-process check contains no cache.
    assert search(composed) == ["Café"]
    assert search(decomposed) == []
    print("Premise contradicted: cache-free lookup still misses decomposed Café.")
    for query in [composed, decomposed, "CAFÉ", "CAFE\u0301"]:
        assert search(query, corrected=True) == ["Café"]
    assert search("Tea", corrected=True) == []
    print("PASS: normalized keys match both forms and preserve case-insensitive lookup.")

def root_cause():
    from types import SimpleNamespace

    def old_avatar(user):
        return user.avatar.url.upper()
    def avatar_display(user):
        if user.avatar is None:
            return "default.svg"
        return user.avatar.url.upper()
    def old_decode(raw):
        return {"balance": raw["balance"]} if raw.get("balance") else {}
    def decode(raw):
        balance = raw["balance"]
        if balance is None:
            raise ValueError("balance is required")
        return {"balance": balance}
    def billing_balance(raw, decoder=decode):
        return decoder(raw)["balance"]

    try:
        old_avatar(SimpleNamespace(avatar=None))
    except AttributeError:
        print("Reproduced: formatter dereferences a contractually valid None.")
    else:
        raise AssertionError("Expected original formatter failure")
    try:
        billing_balance({"balance": 0}, old_decode)
    except KeyError:
        print("Reproduced: decoder discards zero before billing reads it.")
    else:
        raise AssertionError("Expected original decoder failure")
    assert avatar_display(SimpleNamespace(avatar=None)) == "default.svg"
    assert avatar_display(SimpleNamespace(avatar=SimpleNamespace(url="a/b.svg"))) == "A/B.SVG"
    for value in [0, 25, -3]:
        assert billing_balance({"balance": value}) == value
    for invalid in [{}, {"balance": None}]:
        try:
            billing_balance(invalid)
        except (KeyError, ValueError):
            pass
        else:
            raise AssertionError("Missing balance accepted")
    print("PASS: avatar fallback, uppercase URL, zero/nonzero balances, and invalid balance rejection.")

def behavior_tests():
    class Payment:
        def __init__(self):
            self.requests = []
        def charge(self, total_cents):
            self.requests.append({"total_cents": total_cents})
    def _total(cart):
        return sum(cart)
    def checkout(cart, payment):
        if cart:
            payment.charge(_total(cart))
    def checkout_refactored(cart, payment):
        if cart:
            payment.charge(sum(cart))
    def checkout_nothing(cart, payment):
        pass
    def checkout_duplicate(cart, payment):
        checkout(cart, payment)
        checkout(cart, payment)
    def checkout_wrong(cart, payment):
        if cart:
            payment.charge(sum(cart) + 1)
    def checkout_empty_charge(cart, payment):
        payment.charge(sum(cart))
    def contract(implementation):
        empty_payment = Payment()
        implementation([], empty_payment)
        assert empty_payment.requests == [], "empty cart charged"
        paid_payment = Payment()
        implementation([125, 250], paid_payment)
        assert paid_payment.requests == [{"total_cents": 375}], "missing, duplicate, or wrong payment"
    for implementation in [checkout, checkout_refactored]:
        contract(implementation)
        print("PASS:", implementation.__name__)
    for implementation in [checkout_nothing, checkout_duplicate, checkout_wrong, checkout_empty_charge]:
        try:
            contract(implementation)
        except AssertionError as error:
            print("REJECTED:", implementation.__name__, str(error))
        else:
            raise AssertionError("Broken implementation passed: " + implementation.__name__)

def idempotency():
    from copy import deepcopy
    class Crash(Exception):
        pass
    class Service:
        def __init__(self):
            self.records = {}
            self.effects = 0
        def apply(self, job_id, payload, crash_before=False):
            if job_id in self.records:
                previous, result = self.records[job_id]
                if previous != payload:
                    raise ValueError("job ID reused with different payload")
                return result
            if crash_before:
                raise Crash("before service commit")
            # This models the service's assumed atomic, durable commit.
            self.effects += 1
            result = {"receipt": "receipt-" + job_id}
            self.records[job_id] = (deepcopy(payload), result)
            return result
    class Worker:
        def __init__(self, service, local, processes, identity):
            self.service, self.local = service, local
            self.processes, self.identity = processes, identity
        def run(self, job_id, payload, crash=None):
            claim = self.local.get("claim")
            if claim and claim != self.identity:
                pid, start = claim
                if self.processes.get(pid) == start:
                    raise RuntimeError("job still owned by a live process")
                self.local.pop("claim")
            self.local["claim"] = self.identity
            result = self.service.apply(job_id, payload, crash_before=crash == "before")
            if crash == "after":
                raise Crash("after commit, before acknowledgement")
            self.local["ack"] = result
            self.local.pop("claim")
            return result
    for boundary in ["before", "after"]:
        service, local = Service(), {}
        processes = {42: "original-start"}
        original = Worker(service, local, processes, (42, "original-start"))
        try:
            original.run("job-1", {"amount": 100}, crash=boundary)
        except Crash:
            pass
        else:
            raise AssertionError("Crash injection did not run")
        assert "ack" not in local
        assert service.effects == (0 if boundary == "before" else 1)
        committed_result = service.records.get("job-1", (None, None))[1]
        processes[42] = "unrelated-start"
        processes[99] = "recovery-start"
        prior_processes = processes.copy()
        recovered = Worker(service, local, processes, (99, "recovery-start"))
        result = recovered.run("job-1", {"amount": 100})
        for _ in range(3):
            assert recovered.run("job-1", {"amount": 100}) is result
        assert service.effects == 1
        assert local == {"ack": result}
        if committed_result is not None:
            assert result is committed_result
        assert processes == prior_processes
        assert processes[42] == "unrelated-start"
        try:
            recovered.run("job-1", {"amount": 999})
        except ValueError:
            pass
        else:
            raise AssertionError("Changed payload accepted")
        assert service.effects == 1
        assert local["ack"] is result
        assert recovered.run("job-1", {"amount": 100}) is result
        assert "claim" not in local
        print("PASS:", boundary, "commit crash; retries converge to one effect; valid receipt survives; reused PID untouched")
    service, local = Service(), {"claim": (42, "still-live")}
    try:
        Worker(service, local, {42: "still-live", 99: "new"}, (99, "new")).run("job-2", {})
    except RuntimeError:
        assert service.effects == 0
        print("PASS: live matching owner blocks takeover")
    else:
        raise AssertionError("Live owner taken over")


if __name__ == "__main__":
    premise()
    root_cause()
    behavior_tests()
    idempotency()
